import SwiftUI

struct MarketsView: View {
    @EnvironmentObject private var store: AppStore
    var body: some View { NavigationStack { ScrollView { LazyVStack(alignment:.leading,spacing:0) { Eyebrow(text:"DÉCIDER AVANT LES AUTRES");Text("Marchés ouverts").font(.largeTitle.bold()).padding(.top,4);Text("Le prix représente le consensus des joueurs.").foregroundStyle(.konsensMuted).padding(.bottom,22);ForEach(store.markets){market in Button{store.activeMarket=market}{MarketRow(market:market)}.buttonStyle(.plain)} }.padding(18) }.background(Color.konsensBackground).navigationTitle("Marchés").navigationBarTitleDisplayMode(.inline) } }
}
private struct MarketRow:View{let market:Market;var body:some View{HStack(alignment:.top,spacing:15){VStack(alignment:.leading,spacing:9){HStack{Eyebrow(text:market.category);Text("Clôture \(market.closesAt)").font(.caption2).foregroundStyle(.konsensMuted)};Text(market.question).font(.headline);Text("Prendre position →").font(.caption.bold()).foregroundStyle(.konsensGreen)};Spacer();VStack(alignment:.trailing){Text("\(market.yesProbability)%").font(.title2.monospacedDigit().bold());Text("OUI · \(market.movement >= 0 ? "+" : "")\(market.movement)").font(.caption2).foregroundStyle(.konsensGreen)}}.padding(.vertical,19).overlay(alignment:.bottom){Divider().overlay(Color.white.opacity(.09))}}}
struct TradeSheet:View{let market:Market;@EnvironmentObject private var store:AppStore;var body:some View{VStack(alignment:.leading,spacing:18){Eyebrow(text:market.category);Text(market.question).font(.title2.bold());HStack{Text("Consensus actuel").foregroundStyle(.konsensMuted);Spacer();Text("\(market.yesProbability) % OUI").bold().foregroundStyle(.konsensGreen)}.padding().background(Color.black.opacity(.18),in:RoundedRectangle(cornerRadius:13));Text("Investissement de démonstration : 250 crédits.").font(.caption).foregroundStyle(.konsensMuted);HStack{ChoiceButton(title:"Acheter OUI",color:.konsensGreen){store.buy(outcome:true)};ChoiceButton(title:"Acheter NON",color:.red){store.buy(outcome:false)}};Spacer()}.padding(24).background(Color.konsensPanel.ignoresSafeArea())}}
